{
  "groups": [
    {
      "group_id": "low_rate_fixed_high_impact",
      "rule": "rate_type == 'fixed' and origination_year <= 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who secured ultra-low rates are facing the most significant payment shock upon renewal and are highly sensitive to retention offers."
    },
    {
      "group_id": "variable_rate_stretched",
      "rule": "rate_type == 'variable' and credit_score_band in ['600_659', 'below_600']",
      "rationale": "Variable rate borrowers with weaker credit profiles have already experienced payment hikes and have limited options to refinance with other lenders."
    },
    {
      "group_id": "high_debt_family_burden",
      "rule": "n_children >= 2 and household_income_cad < 75000",
      "rationale": "Families with multiple children and lower income levels have limited budget elasticity to absorb rising mortgage costs or inflation."
    },
    {
      "group_id": "uninsured_high_utilization",
      "rule": "insured_flag == False and credit_utilization_pct > 50",
      "rationale": "Uninsured borrowers with high credit usage are constrained by the stress test and may struggle to qualify elsewhere due to high debt levels."
    },
    {
      "group_id": "prime_insured_stable",
      "rule": "insured_flag == True and credit_score_band == '720_plus' and has_savings == True",
      "rationale": "High credit score insured borrowers with existing savings are low-risk customers who are attractive to competitors but have high loyalty potential."
    },
    {
      "group_id": "recent_buyer_high_rate",
      "rule": "origination_year >= 2022 and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers who entered the market at the peak of rates have no equity buffer and may be experiencing immediate financial stress."
    },
    {
      "group_id": "self_employed_complex",
      "rule": "employment_status == 'self_employed' and other_debt_payment_monthly_cad > 500",
      "rationale": "Self-employed borrowers often face higher documentation hurdles when switching lenders, keeping them tethered to their current institution."
    }
  ]
}
